/* ── Showreel video player — inline, lazy, no autoplay ────────
   The most important section for a video editor portfolio.       */
const ShowreelPlayer = memo(function ShowreelPlayer({ t }) {
  const videoRef    = useRef(null);
  const wrapRef     = useRef(null);
  const playBtnRef  = useRef(null);

  const handlePlay = useCallback(() => {
    const video = videoRef.current;
    const wrap  = wrapRef.current;
    if (!video || !wrap) return;
    /* Reveal the native player and start playback */
    wrap.classList.add('showreel__player--playing');
    video.play().catch(() => {
      /* If autoplay blocked, show controls so user can tap */
      video.controls = true;
    });
  }, []);

  /* Keyboard: Enter/Space triggers play */
  const handleKeyDown = useCallback((e) => {
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      handlePlay();
    }
  }, [handlePlay]);

  return (
    <div className="showreel__player-wrap" ref={wrapRef}>
      {/* Poster + play overlay — shown until play is triggered */}
      <div className="showreel__poster" onClick={handlePlay}
        onKeyDown={handleKeyDown} role="button" tabIndex={0}
        aria-label={t('showreel_play')}>

        {/* P5-style poster artwork — pure CSS, no external image needed */}
        <div className="showreel__poster-bg" aria-hidden="true">
          <div className="showreel__poster-slash" />
          <div className="showreel__poster-slash showreel__poster-slash--2" />
          <div className="showreel__poster-grid" />
        </div>

        {/* Film-frame corner decorations */}
        <div className="showreel__corner showreel__corner--tl" aria-hidden="true" />
        <div className="showreel__corner showreel__corner--tr" aria-hidden="true" />
        <div className="showreel__corner showreel__corner--bl" aria-hidden="true" />
        <div className="showreel__corner showreel__corner--br" aria-hidden="true" />

        {/* Centre play button */}
        <div className="showreel__play-btn" aria-hidden="true" ref={playBtnRef}>
          <div className="showreel__play-ring" />
          <div className="showreel__play-ring showreel__play-ring--2" />
          <svg className="showreel__play-icon" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">
            <path d="M8 5.14v14l11-7-11-7z" />
          </svg>
        </div>

        {/* Poster metadata */}
        <div className="showreel__poster-meta" aria-hidden="true">
          <span className="showreel__poster-label">{t('showreel_label')}</span>
          <span className="showreel__poster-year">{t('showreel_year')}</span>
        </div>
      </div>

      {/* Actual video — hidden until play is triggered (no autoplay, lazy) */}
      <video
        ref={videoRef}
        className="showreel__video"
        preload="none"
        playsInline
        controlsList="nodownload"
        aria-label={t('showreel_title')}
        /* Replace src with your real showreel URL */
        src=""
        poster=""
      />
    </div>
  );
});

